const mongoose = require("mongoose");

const messageSchema = new mongoose.Schema(
  {
    conversation: {
      type: mongoose.Schema.Types.ObjectId,
      ref: "Conversation",
      required: true,
      index: true,
    },

    sender: {
      type: mongoose.Schema.Types.ObjectId,
      ref: "User",
      required: true,
      index: true,
    },

    /*
     * Generated by the client for each send attempt.
     *
     * Used to make retries idempotent.
     */
    clientMessageId: {
      type: String,
      required: true,
      trim: true,
      maxlength: 100,
    },

    type: {
      type: String,
      enum: ["text"],
      default: "text",
      required: true,
    },

    text: {
      type: String,
      required: true,
      trim: true,
      maxlength: 2000,
    },

    editedAt: {
      type: Date,
      default: null,
    },

    deletedAt: {
      type: Date,
      default: null,
    },
  },
  {
    timestamps: true,
  }
);

/*
 * Primary history pagination index.
 *
 * We use createdAt + _id as the cursor.
 */
messageSchema.index({
  conversation: 1,
  createdAt: -1,
  _id: -1,
});

/*
 * Idempotency protection.
 *
 * The same sender cannot create the same
 * clientMessageId twice inside one conversation.
 */
messageSchema.index(
  {
    conversation: 1,
    sender: 1,
    clientMessageId: 1,
  },
  {
    unique: true,
  }
);

module.exports = mongoose.model(
  "Message",
  messageSchema
);